/**
 * Escapes the 5 essential HTML characters to their safe entity equivalents.
 * Prevents user input from breaking out of text nodes into HTML elements.
 */
function escapeHtml(str) {
  if (typeof str !== 'string') return '';

  const htmlEntityMap = {
    '&': '&amp;',
    '<': '&lt;',
    '>': '&gt;',
    '"': '&quot;',
    "'": '&#x27;'
  };

  return str.replace(/[&<>"']/g, (char) => htmlEntityMap[char]);
}

// Example demonstration:
