/**
 * Whitelist validation defines strictly what IS permitted.
 * Blacklist validation attempts to catch known bad characters, which attackers routinely bypass.
 */
function validateUsername(username) {
  // Must be a string
  if (typeof username !== 'string') {
    return { isValid: false, reason: 'Username must be a string' };
  }

  // Whitelist rule: Alphanumeric characters, underscores, and hyphens only
  // Length constraint: between 3 and 20 characters
  const usernamePattern = /^[a-zA-Z0-9_-]{3,20}$/;

  if (!usernamePattern.test(username)) {
    return {
      isValid: false,
      reason: 'Username must be 3-20 characters long and contain only letters, numbers, hyphens, and underscores.'
    };
  }

  return { isValid: true };
}

// Tests
console.log(validateUsername('alice_2026')); // { isValid: true }
console.log(validateUsername('<script>')); // { isValid: false, reason: '...' }

